CREATE OR REPLACE FUNCTION public.campaign_carrier_price_groups(_campaign_id uuid) RETURNS TABLE(sender_used text, sent_day text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT DISTINCT m.sender_used, to_char(m.sent_at AT TIME ZONE 'UTC', 'YYYY-MM-DD') FROM public.messages m WHERE m.campaign_id = _campaign_id AND m.provider_message_id LIKE 'SM%' AND m.sent_at IS NOT NULL AND m.sender_used IS NOT NULL ORDER BY 1,2; $$; REVOKE ALL ON FUNCTION public.campaign_carrier_price_groups(uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.campaign_carrier_price_groups(uuid) TO service_role; CREATE OR REPLACE FUNCTION public.record_campaign_carrier_prices(_campaign_id uuid, _rows jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE changed integer; BEGIN IF jsonb_typeof(_rows) <> 'array' OR jsonb_array_length(_rows) > 1000 THEN RAISE EXCEPTION 'Invalid price batch'; END IF; UPDATE public.messages m SET carrier_price = r.carrier_price, carrier_price_checked_at = now() FROM jsonb_to_recordset(_rows) AS r(id uuid, provider_message_id text, carrier_price numeric) WHERE m.id = r.id AND m.campaign_id = _campaign_id AND m.provider_message_id = r.provider_message_id AND m.carrier_price IS NULL AND r.carrier_price >= 0; GET DIAGNOSTICS changed = ROW_COUNT; RETURN changed; END; $$; REVOKE ALL ON FUNCTION public.record_campaign_carrier_prices(uuid,jsonb) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.record_campaign_carrier_prices(uuid,jsonb) TO service_role;